class Solution {
public:
    int minimumFlips(int n) {
        string bits;
        while (n > 0) {
            bits.push_back(char('0' + (n & 1)));
            n >>= 1;
        }
        int ans = 0;
        for (int i = 0, j = (int)bits.size() - 1; i < j; ++i, --j) {
            if (bits[i] != bits[j]) ans += 2;
        }
        return ans;
    }
};
